import pandas as pd


def run(inputs: dict) -> dict:
    dim_price = inputs["dim_price"].copy()
    stg_price = inputs["stg_price"].copy()
    batch_date = inputs["batch_control"]["batch_date"].iloc[0]

    # Build per-product version lists from existing DIM_PRICE
    versions = {}  # product_id -> list of dicts: list_price, eff_start_date, eff_end_date
    for _, row in dim_price.iterrows():
        pid = row["product_id"]
        versions.setdefault(pid, []).append({
            "list_price": row["list_price"],
            "eff_start_date": row["eff_start_date"],
            "eff_end_date": row["eff_end_date"],
        })

    # Determine current "tail" (version with latest eff_start_date) per product
    tails = {}
    for pid, vlist in versions.items():
        vlist.sort(key=lambda v: v["eff_start_date"])
        tails[pid] = vlist[-1] if vlist else None

    # Process staged rows: group by product, order by effective_date ascending
    stg_sorted = stg_price.sort_values(["product_id", "effective_date"], kind="mergesort")

    for _, s in stg_sorted.iterrows():
        pid = s["product_id"]
        tail = tails.get(pid)

        if tail is not None and tail["list_price"] == s["list_price"]:
            # unchanged -> no new version
            continue

        if tail is not None:
            tail["eff_end_date"] = s["effective_date"]

        new_v = {
            "list_price": s["list_price"],
            "eff_start_date": s["effective_date"],
            "eff_end_date": None,
        }
        versions.setdefault(pid, []).append(new_v)
        tails[pid] = new_v

    # Recompute is_current for every version of every product based on batch_date
    rows = []
    for pid, vlist in versions.items():
        for v in vlist:
            start = v["eff_start_date"]
            end = v["eff_end_date"]
            if pd.isna(end):
                is_current = 1 if start <= batch_date else 0
            else:
                is_current = 1 if (start <= batch_date < end) else 0
            rows.append({
                "product_id": pid,
                "list_price": v["list_price"],
                "eff_start_date": start,
                "eff_end_date": end,
                "is_current": is_current,
            })

    out = pd.DataFrame(
        rows,
        columns=["product_id", "list_price", "eff_start_date", "eff_end_date", "is_current"],
    )

    if not out.empty:
        out = out.sort_values(["product_id", "eff_start_date"], kind="mergesort").reset_index(drop=True)

    out["product_id"] = out["product_id"].astype("int64")
    out["list_price"] = out["list_price"].astype("float64")
    out["eff_start_date"] = pd.to_datetime(out["eff_start_date"])
    out["eff_end_date"] = pd.to_datetime(out["eff_end_date"])
    out["is_current"] = out["is_current"].astype("int64")

    return {"dim_price_out": out}
